package com.codeguardian.service.rag; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.*;
@Service public class HybridRetrievalService{private final List<KnowledgeDocument> docs=List.of(doc("sql-injection","SQL injection","Use parameterized statements for database queries.","Use prepared statements and bind parameters."),doc("resource-close","Resource management","Close file and network resources using try-with-resources.","Wrap resources in try-with-resources."),doc("null-safety","Null safety","Validate nullable inputs before dereferencing them.","Use null checks or Optional appropriately."));private KnowledgeDocument doc(String i,String t,String c,String s){return KnowledgeDocument.builder().id(i).title(t).content(c).solution(s).build();}public List<KnowledgeDocument> search(String q,int k){List<String> terms=terms(q);Map<KnowledgeDocument,Double> score=new HashMap<>();for(KnowledgeDocument d:docs){Set<String> dt=new HashSet<>(terms(d.getTitle()+" "+d.getContent()));long overlap=terms.stream().filter(dt::contains).count();double semantic=terms.isEmpty()?0:(double)overlap/Math.sqrt(terms.size()*dt.size());score.put(d,overlap+semantic);}return score.entrySet().stream().sorted(Map.Entry.<KnowledgeDocument,Double>comparingByValue().reversed()).limit(k).map(Map.Entry::getKey).toList();}public String context(String q){return search(q,3).stream().map(d->"## "+d.getTitle()+"\n"+d.getContent()+"\nFix: "+d.getSolution()).collect(Collectors.joining("\n\n"));}private List<String> terms(String s){return Arrays.stream(s.toLowerCase().split("[^a-z0-9_]+" )).filter(x->!x.isBlank()).toList();}}
